    "kind": "dev",
    "methods": {
      "constructor": {
        "custom:oz-upgrades-unsafe-allow": "constructor",
        "params": {
          "_factory": "The factory that approves upgrade targets. Must have code:        the value cannot be corrected after this point.",
          "_protocolSafe": "The protocol safe this deploy expects the factory to        name. Not proof of ownership: what binds this implementation to the        protocol is the protocol safe's `setImplementation` on that factory."
        }
      },
      "initialize(address,bytes)": {
        "details": "Called by the factory, in the same call that deployed this proxy, with      the Safe the factory recorded. `params` is `abi.encode(string[] keys,      string[] values)` for records to seed, or empty.      Seeding emits `RecordsSetBatch` like any other batch write: an indexer      watching the event sees every record, including the ones the module      started with.      The protocol Safe may create this module on a publication's behalf and      choose the seeded records. That is intended: it is the same authority      that approves builds, and the Safe can rewrite any record after."
      },
      "proxiableUUID()": {
        "details": "Implementation of the ERC1822 {proxiableUUID} function. This returns the storage slot used by the implementation. It is used to validate the implementation's compatibility when performing an upgrade. IMPORTANT: A proxy pointing at a proxiable contract should not be considered proxiable itself, because this risks bricking a proxy that upgrades to it, by delegating to itself until out of gas. Thus it is critical that this function revert if invoked through a proxy. This is guaranteed by the `notDelegated` modifier."
      },
      "upgradeTo(address)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      },
      "upgradeToAndCall(address,bytes)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`, and subsequently execute the function call encoded in `data`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      }
    },
    "stateVariables": {
      "FACTORY": {
        "details": "The factory whose approved set decides what this module may upgrade      to. Immutable: no storage write can change it, and it is the same      answer for every proxy over this implementation."
      }
    },
